// Home hero: a glowing metasurface antenna radiating.
//  - unit cells light up with the outward surface-current wave
//  - detached E-field loops (r = L·sin²θ) are born at the feed and propagate outward
//  - expanding hemispherical wavefronts + ground ripples
//  - photon-like sparks streaming off the aperture
import { threeScene, THREE, lowPower } from "./core/threeScene.js";
import * as fallback from "./metasurfaceLite.js";
import { motionAllowed } from "./core/manager.js";

let instance;

function glowTexture() {
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const g = c.getContext("2d");
  const grad = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  grad.addColorStop(0, "rgba(255,255,255,1)");
  grad.addColorStop(0.25, "rgba(255,255,255,0.55)");
  grad.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = grad;
  g.fillRect(0, 0, 64, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function init(container, options = {}) {
  destroy();
  try {
    instance = threeScene(
      container,
      ({ scene, camera }) => {
        camera.position.set(8.2, 7.2, 10.2);
        camera.lookAt(0, 1.4, 0);
        scene.fog = new THREE.FogExp2(0x040608, 0.035);
        scene.add(new THREE.AmbientLight(0xffffff, 1.2));
        const key = new THREE.DirectionalLight(0xd9fff0, 2.4);
        key.position.set(4, 8, 3);
        scene.add(key);
        const rim = new THREE.PointLight(0x35e3ff, 30, 18);
        rim.position.set(-4, 3, -3);
        scene.add(rim);

        const glow = glowTexture();
        const add = THREE.AdditiveBlending;
        const group = new THREE.Group();
        group.rotation.y = -0.2;
        scene.add(group);

        // --- substrate + ground ---
        const n = lowPower ? 5 : 9,
          size = 5.6;
        const substrate = new THREE.Mesh(
          new THREE.BoxGeometry(size, 0.2, size),
          new THREE.MeshStandardMaterial({
            color: 0x071a16,
            metalness: 0.4,
            roughness: 0.7,
            emissive: 0x03140d,
          }),
        );
        group.add(substrate);
        const ground = new THREE.Mesh(
          new THREE.BoxGeometry(size + 0.06, 0.035, size + 0.06),
          new THREE.MeshStandardMaterial({
            color: 0x6f8580,
            metalness: 0.9,
            roughness: 0.3,
          }),
        );
        ground.position.y = -0.13;
        group.add(ground);
        const edges = new THREE.LineSegments(
          new THREE.EdgesGeometry(substrate.geometry),
          new THREE.LineBasicMaterial({
            color: 0x3dff9e,
            transparent: true,
            opacity: 0.8,
            blending: add,
          }),
        );
        group.add(edges);

        // --- unit cells ---
        const pitch = size / n;
        const cellGeometry = new THREE.BoxGeometry(
          pitch * 0.74,
          0.04,
          pitch * 0.74,
        );
        const slotGeometry = new THREE.EdgesGeometry(
          new THREE.PlaneGeometry(pitch * 0.42, pitch * 0.42),
        );
        const cells = [];
        for (let x = 0; x < n; x++)
          for (let z = 0; z < n; z++) {
            const material = new THREE.MeshStandardMaterial({
              color: 0x7b9590,
              metalness: 0.85,
              roughness: 0.35,
              emissive: 0x35e3ff,
              emissiveIntensity: 0,
            });
            const mesh = new THREE.Mesh(cellGeometry, material);
            mesh.position.set(
              (x - (n - 1) / 2) * pitch,
              0.12,
              (z - (n - 1) / 2) * pitch,
            );
            const slot = new THREE.LineSegments(
              slotGeometry,
              new THREE.LineBasicMaterial({
                color: 0x3dff9e,
                transparent: true,
                opacity: 0.2,
                blending: add,
              }),
            );
            slot.rotation.x = -Math.PI / 2;
            slot.position.y = 0.03;
            mesh.add(slot);
            group.add(mesh);
            cells.push({
              mesh,
              slot,
              r: Math.hypot(mesh.position.x, mesh.position.z),
              a: Math.atan2(mesh.position.z, mesh.position.x),
            });
          }

        // --- feed ---
        const feed = new THREE.Mesh(
          new THREE.SphereGeometry(0.13, 16, 12),
          new THREE.MeshBasicMaterial({ color: 0xff3d3d }),
        );
        feed.position.y = 0.22;
        group.add(feed);
        const feedGlow = new THREE.Sprite(
          new THREE.SpriteMaterial({
            map: glow,
            color: 0xff3d3d,
            blending: add,
            transparent: true,
            depthWrite: false,
          }),
        );
        feedGlow.position.y = 0.25;
        group.add(feedGlow);

        // --- hemispherical wavefronts ---
        const shellGeo = new THREE.SphereGeometry(
          1,
          lowPower ? 24 : 40,
          lowPower ? 8 : 14,
          0,
          Math.PI * 2,
          0,
          Math.PI / 2,
        );
        const shells = [];
        for (let i = 0; i < 5; i++) {
          const shell = new THREE.Mesh(
            shellGeo,
            new THREE.MeshBasicMaterial({
              color: 0x35e3ff,
              wireframe: true,
              transparent: true,
              opacity: 0.1,
              blending: add,
              depthWrite: false,
            }),
          );
          shell.position.y = 0.2;
          group.add(shell);
          shells.push(shell);
        }

        // --- ground ripples ---
        const ringGeo = new THREE.RingGeometry(0.985, 1, lowPower ? 64 : 128);
        const rings = [];
        for (let i = 0; i < 6; i++) {
          const ring = new THREE.Mesh(
            ringGeo,
            new THREE.MeshBasicMaterial({
              color: 0x3dff9e,
              transparent: true,
              opacity: 0.3,
              side: THREE.DoubleSide,
              depthWrite: false,
              blending: add,
            }),
          );
          ring.rotation.x = -Math.PI / 2;
          ring.position.y = 0.16;
          group.add(ring);
          rings.push(ring);
        }

        // --- radiating E-field loops ---
        const AZ = lowPower ? 8 : 14; // azimuthal planes
        const LOOPS = lowPower ? 3 : 5; // loops alive per plane
        const SEG = lowPower ? 26 : 44; // segments per loop
        const Lmax = 7.5;
        const loopVerts = AZ * LOOPS * SEG * 2;
        const loopPos = new Float32Array(loopVerts * 3);
        const loopCol = new Float32Array(loopVerts * 3);
        const loopGeo = new THREE.BufferGeometry();
        loopGeo.setAttribute("position", new THREE.BufferAttribute(loopPos, 3));
        loopGeo.setAttribute("color", new THREE.BufferAttribute(loopCol, 3));
        const loopMat = new THREE.LineBasicMaterial({
          vertexColors: true,
          transparent: true,
          blending: add,
          depthWrite: false,
        });
        const loops = new THREE.LineSegments(loopGeo, loopMat);
        loops.position.y = 0.2;
        group.add(loops);

        // --- sparks ---
        const SPARKS = lowPower ? 140 : 420;
        const sparkPos = new Float32Array(SPARKS * 3);
        const sparkCol = new Float32Array(SPARKS * 3);
        const sparkSeed = Array.from({ length: SPARKS }, () => ({
          a: Math.random() * Math.PI * 2,
          el: 0.25 + Math.random() * 1.2,
          p: Math.random(),
          s: 0.5 + Math.random() * 0.8,
        }));
        const sparkGeo = new THREE.BufferGeometry();
        sparkGeo.setAttribute(
          "position",
          new THREE.BufferAttribute(sparkPos, 3),
        );
        sparkGeo.setAttribute("color", new THREE.BufferAttribute(sparkCol, 3));
        const sparks = new THREE.Points(
          sparkGeo,
          new THREE.PointsMaterial({
            size: 0.16,
            map: glow,
            vertexColors: true,
            transparent: true,
            blending: add,
            depthWrite: false,
            sizeAttenuation: true,
          }),
        );
        sparks.position.y = 0.2;
        group.add(sparks);

        const grid = new THREE.GridHelper(14, 28, 0x25574a, 0x16302a);
        grid.position.y = -0.25;
        grid.material.transparent = true;
        grid.material.opacity = 0.55;
        scene.add(grid);

        const cP = new THREE.Color(),
          cC = new THREE.Color(),
          cR = new THREE.Color(),
          tmp = new THREE.Color();
        let px = 0,
          py = 0;
        const pointer = (e) => {
          if (!motionAllowed()) return;
          px = e.clientX / innerWidth - 0.5;
          py = e.clientY / innerHeight - 0.5;
        };
        window.addEventListener("pointermove", pointer, { passive: true });

        return {
          update(t, dt, still, c) {
            const phase = still && !motionAllowed() ? 2.4 : t;
            cP.set(c.phosphor || "#3dff9e");
            cC.set(c.cyan || "#35e3ff");
            cR.set(c.accent || "#ff3d3d");
            if (c.bg) scene.fog.color.set(c.bg);
            group.rotation.y =
              -0.2 +
              Math.sin(phase * 0.09) * 0.16 +
              (motionAllowed() ? px * 0.18 : 0);
            group.rotation.x = motionAllowed() ? py * 0.05 : 0;

            // feed
            const pulse = 0.5 + 0.5 * Math.sin(phase * 5);
            feed.scale.setScalar(1 + 0.25 * pulse);
            feedGlow.scale.setScalar(1.4 + 1.2 * pulse);

            // surface currents: outward travelling wave, with a rotating CP component
            cells.forEach(({ mesh, slot, r, a }) => {
              const wave = 0.5 + 0.5 * Math.cos(4.4 * r - phase * 3.2);
              const cp = 0.5 + 0.5 * Math.cos(a - phase * 1.6);
              const e = wave ** 6 * (0.55 + 0.45 * cp);
              mesh.material.emissiveIntensity = 0.05 + 1.6 * e;
              mesh.material.emissive.copy(cC).lerp(cP, cp * 0.6);
              slot.material.opacity = 0.15 + 0.85 * e;
              slot.material.color.copy(cP);
            });
            edges.material.color.copy(cP);

            // wavefront shells
            shells.forEach((shell, i) => {
              const p = (phase * 0.16 + i / shells.length) % 1;
              shell.scale.setScalar(0.3 + p * 7.5);
              shell.material.opacity =
                0.16 * Math.sin(Math.PI * p) * (1 - p * 0.5);
              shell.material.color.copy(cC);
              shell.rotation.y = phase * 0.05;
            });
            rings.forEach((ring, i) => {
              const p = (phase * 0.2 + i / rings.length) % 1;
              ring.scale.setScalar(0.3 + p * 6.5);
              ring.material.opacity =
                0.45 * Math.sin(Math.PI * p) * (1 - p * 0.6);
              ring.material.color.copy(cP);
            });

            // E-field loops: r = L sin²θ, θ ∈ [θ0, π/2]; loops detach as L grows
            let v = 0;
            for (let az = 0; az < AZ; az++) {
              const phi = (az / AZ) * Math.PI * 2;
              const cph = Math.cos(phi),
                sph = Math.sin(phi);
              for (let k = 0; k < LOOPS; k++) {
                const life = (phase * 0.11 + k / LOOPS + az * 0.013) % 1;
                const L = 0.6 + life * Lmax;
                const rMin = Math.min(
                  0.92 * L,
                  0.25 + Math.max(0, L - 1.8) * 0.72,
                );
                const th0 = Math.asin(Math.sqrt(Math.min(0.999, rMin / L)));
                const fade = Math.sin(Math.PI * life) ** 1.4;
                tmp
                  .copy(cC)
                  .lerp(cP, life)
                  .multiplyScalar(0.55 * fade);
                let prev = null;
                for (let s = 0; s <= SEG; s++) {
                  const th = th0 + (Math.PI / 2 - th0) * (s / SEG);
                  const r = L * Math.sin(th) ** 2;
                  const rho = r * Math.sin(th),
                    y = r * Math.cos(th);
                  const cur = [rho * cph, y, rho * sph];
                  if (prev) {
                    const bright = 0.35 + 0.65 * Math.sin((s / SEG) * Math.PI);
                    for (const pt of [prev, cur]) {
                      loopPos[v * 3] = pt[0];
                      loopPos[v * 3 + 1] = pt[1];
                      loopPos[v * 3 + 2] = pt[2];
                      loopCol[v * 3] = tmp.r * bright;
                      loopCol[v * 3 + 1] = tmp.g * bright;
                      loopCol[v * 3 + 2] = tmp.b * bright;
                      v++;
                    }
                  }
                  prev = cur;
                }
              }
            }
            loopGeo.attributes.position.needsUpdate = true;
            loopGeo.attributes.color.needsUpdate = true;

            // sparks
            sparkSeed.forEach((sp, i) => {
              const life = (phase * 0.22 * sp.s + sp.p) % 1;
              const r = 0.2 + life * 7;
              const el = sp.el;
              sparkPos[i * 3] = r * Math.cos(el) * Math.cos(sp.a);
              sparkPos[i * 3 + 1] = r * Math.sin(el);
              sparkPos[i * 3 + 2] = r * Math.cos(el) * Math.sin(sp.a);
              const f = (1 - life) ** 1.5;
              tmp.copy(life < 0.15 ? cR : cC).lerp(cP, life);
              sparkCol[i * 3] = tmp.r * f;
              sparkCol[i * 3 + 1] = tmp.g * f;
              sparkCol[i * 3 + 2] = tmp.b * f;
            });
            sparkGeo.attributes.position.needsUpdate = true;
            sparkGeo.attributes.color.needsUpdate = true;
          },
          dispose() {
            window.removeEventListener("pointermove", pointer);
            glow.dispose();
          },
        };
      },
      options,
    );
  } catch {
    container.querySelectorAll("canvas").forEach((c) => c.remove());
    fallback.init(container, options);
    instance = { destroy: () => fallback.destroy() };
  }
  return instance;
}

export function destroy() {
  instance?.destroy();
  instance = null;
}
